#!/usr/bin/env python3
"""Validate data/commitments.csv against the sourcing protocol.

Usage: python scripts/validate.py [path/to/commitments.csv]
Exit code 0 = clean, 1 = problems found. No dependencies beyond the stdlib.
"""
import csv
import json
import re
import sys
from datetime import date
from pathlib import Path

REQUIRED = [
    "commitment_id", "version", "developer", "category", "text_verbatim",
    "source_url", "archive_url", "accessed_on", "first_seen", "strength",
    "confidence", "entered_by",
]
CATEGORIES = {"capability-threshold", "eval-before-deploy", "security", "incident-disclosure",
              "third-party-access", "pause-condition", "governance", "other"}
STRENGTHS = {"binding-specific", "specific", "aspirational", "removed"}
CONFIDENCE = {"high", "medium", "low"}
SLUG = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")
URL = re.compile(r"^https?://\S+$")


def parse_date(s):
    return date.fromisoformat(s) if s else None


def main(path):
    problems = []
    seen = set()
    with open(path, newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))
    if not rows:
        print("Dataset is empty (header only). Nothing to validate.")
        return 0
    for i, r in enumerate(rows, start=2):  # line 1 is header
        where = f"line {i} ({r.get('commitment_id', '?')})"
        for k in REQUIRED:
            if not (r.get(k) or "").strip():
                problems.append(f"{where}: missing required field '{k}'")
        if r.get("commitment_id") and not SLUG.match(r["commitment_id"]):
            problems.append(f"{where}: commitment_id is not a lowercase slug")
        try:
            v = int(r.get("version", ""))
            key = (r.get("commitment_id"), v)
            if key in seen:
                problems.append(f"{where}: duplicate commitment_id/version")
            seen.add(key)
        except ValueError:
            problems.append(f"{where}: version must be an integer")
        if r.get("category") not in CATEGORIES:
            problems.append(f"{where}: bad category '{r.get('category')}'")
        if r.get("strength") not in STRENGTHS:
            problems.append(f"{where}: bad strength '{r.get('strength')}'")
        if r.get("confidence") not in CONFIDENCE:
            problems.append(f"{where}: bad confidence '{r.get('confidence')}'")
        for k in ("source_url", "archive_url"):
            if r.get(k) and not URL.match(r[k]):
                problems.append(f"{where}: {k} does not look like a URL")
        try:
            acc, first, sup = (parse_date(r.get("accessed_on")), parse_date(r.get("first_seen")),
                               parse_date(r.get("superseded_on")))
            if first and acc and first > acc:
                problems.append(f"{where}: first_seen is after accessed_on")
            if sup and first and sup < first:
                problems.append(f"{where}: superseded_on is before first_seen")
        except ValueError as e:
            problems.append(f"{where}: bad date: {e}")
        obs = (r.get("observations_json") or "").strip()
        if obs:
            try:
                items = json.loads(obs)
                for o in items:
                    for k in ("date", "note", "source_url"):
                        if not o.get(k):
                            problems.append(f"{where}: observation missing '{k}'")
            except json.JSONDecodeError:
                problems.append(f"{where}: observations_json is not valid JSON")
    if problems:
        print("\n".join(problems))
        print(f"\n{len(problems)} problem(s) in {len(rows)} row(s).")
        return 1
    print(f"OK: {len(rows)} row(s) valid.")
    return 0


if __name__ == "__main__":
    default = Path(__file__).resolve().parent.parent / "data" / "commitments.csv"
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else default))
